"use client";

import React, { useState, useMemo, useRef, useEffect } from "react";
import { 
  Calendar as CalendarIcon, ChevronDown, CheckCircle2, UploadCloud, 
  Plane, Stethoscope, Briefcase, Baby, Umbrella, Heart, AlertOctagon, 
  Trash2, ArrowRight, User, AlertTriangle, RefreshCcw, Sparkles, 
  Clock, RotateCcw, ChevronLeft, ChevronRight, Info
} from "lucide-react";

// ============================================================================
// 🛠️ CONFIGURATION (Restored Full Config)
// ============================================================================
const COMPANY_CONFIG = {
  holidays: [
    { date: "2026-01-26", name: "Republic Day" },
    { date: "2026-02-14", name: "Valentine's" },
    { date: "2026-03-25", name: "Holi" }
  ],
  history: [
    { date: "2026-01-05", status: "approved", label: "Sick Leave" },
    { date: "2026-01-06", status: "approved", label: "Sick Leave" },
    { date: "2026-01-12", status: "rejected", label: "Casual" }, 
    { date: "2026-02-10", status: "pending", label: "Vacation" }, 
  ],
  leaveTypes: [
    { id: "annual", label: "Annual", icon: Plane, balance: 18, accrual: 1.5, color: "text-blue-500", bg: "bg-blue-500/10", requiresDoc: false },
    { id: "sick", label: "Sick", icon: Stethoscope, balance: 12, accrual: 1.0, color: "text-rose-500", bg: "bg-rose-500/10", requiresDoc: true },
    { id: "casual", label: "Casual", icon: Briefcase, balance: 6, accrual: 0.5, color: "text-amber-500", bg: "bg-amber-500/10", requiresDoc: false },
    { id: "comp", label: "Comp Off", icon: Umbrella, balance: 3, accrual: 0, color: "text-emerald-500", bg: "bg-emerald-500/10", requiresDoc: false },
    { id: "mat", label: "Maternity", icon: Baby, balance: 90, accrual: 0, color: "text-purple-500", bg: "bg-purple-500/10", requiresDoc: true },
    { id: "ber", label: "Bereave", icon: Heart, balance: 5, accrual: 0, color: "text-slate-500", bg: "bg-slate-500/10", requiresDoc: false },
    { id: "lop", label: "L.O.P", icon: AlertOctagon, balance: 0, accrual: 0, color: "text-red-500", bg: "bg-red-500/10", requiresDoc: false },
  ],
  approvers: [
    { name: "Sarah J.", role: "Manager", avatar: "SJ" },
    { name: "HR Dept", role: "Audit", avatar: "HR" }
  ],
  colleagues: [
    { id: 1, name: "Mike Ross", role: "Backend" },
    { id: 2, name: "Rachel Zane", role: "Paralegal" },
  ]
};

export default function SingleScreenPortal() {
  // --- STATE ---
  const [currentDate, setCurrentDate] = useState(new Date(2026, 0, 1));
  const [mode, setMode] = useState<"single" | "range" | "multi">("range");
  
  // Selection
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [multiDates, setMultiDates] = useState<string[]>([]);
  
  // Form
  const [typeId, setTypeId] = useState("annual");
  const [coverId, setCoverId] = useState("");
  const [reason, setReason] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  
  const dropdownRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- LOGIC: RESTORED & ROBUST ---
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const calendarData = useMemo(() => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    let firstDayOfWeek = new Date(year, month, 1).getDay();
    firstDayOfWeek = firstDayOfWeek === 0 ? 6 : firstDayOfWeek - 1; 
    return { year, month, daysInMonth, firstDayOfWeek };
  }, [currentDate]);

  // RESTORED: The smart selection logic that handles re-clicking correctly
  const handleDateClick = (day: number) => {
    const y = calendarData.year;
    const m = calendarData.month + 1;
    const dStr = `${y}-${m < 10 ? '0' + m : m}-${day < 10 ? '0' + day : day}`;

    const existing = COMPANY_CONFIG.history.find(r => r.date === dStr);
    if (existing && (existing.status === 'approved' || existing.status === 'pending')) return;

    if (mode === "multi") {
      setMultiDates(prev => prev.includes(dStr) ? prev.filter(d => d !== dStr) : [...prev, dStr].sort());
    } else if (mode === "single") {
      setRange({ start: dStr, end: dStr });
    } else {
      // Range Logic: If valid range exists, START NEW. If partial, COMPLETE IT.
      if (!range.start || (range.start && range.end)) {
        setRange({ start: dStr, end: "" });
      } else {
        const s = new Date(range.start);
        const e = new Date(dStr);
        if (e < s) setRange({ start: dStr, end: range.start }); 
        else setRange({ ...range, end: dStr });
      }
    }
  };

  const stats = useMemo(() => {
    let days = 0, deduction = 0, sandwichWarning = false, projection = 0;
    
    const checkDay = (dStr: string) => {
      const dObj = new Date(dStr);
      const isHoliday = COMPANY_CONFIG.holidays.some(h => h.date === dStr);
      const isWeekend = dObj.getDay() === 0 || dObj.getDay() === 6;
      if (!isHoliday && !isWeekend) return 1;
      return 0;
    };

    if (mode === "multi") {
      days = multiDates.length;
      deduction = multiDates.reduce((acc, date) => acc + checkDay(date), 0);
    } else {
      if (range.start && range.end) {
        let cur = new Date(range.start);
        let end = new Date(range.end);
        if (cur.getDay() === 5 && end.getDay() === 1) sandwichWarning = true;
        while (cur <= end) {
          deduction += checkDay(cur.toISOString().split('T')[0]);
          days++;
          cur.setDate(cur.getDate() + 1);
        }
      } else if (range.start) {
         days = 1;
         deduction = checkDay(range.start);
      }
    }

    const selectedType = COMPANY_CONFIG.leaveTypes.find(t => t.id === typeId)!;
    const today = new Date();
    const monthDiff = (calendarData.year - today.getFullYear()) * 12 + (calendarData.month - today.getMonth());
    if (monthDiff > 0 && selectedType.accrual > 0) projection = Number((monthDiff * selectedType.accrual).toFixed(1));

    return { days, deduction, sandwichWarning, projection };
  }, [range, multiDates, mode, typeId, calendarData]);

  const selectedType = COMPANY_CONFIG.leaveTypes.find(t => t.id === typeId)!;
  const isCoverRequired = stats.deduction > 3;
  const hasDates = mode === "multi" ? multiDates.length > 0 : !!(range.start && range.end);
  const isBtnDisabled = !hasDates || !reason.trim() || (selectedType.requiresDoc && !file) || (isCoverRequired && !coverId);

  return (
    <div className="h-screen w-full bg-[#fafafa] dark:bg-[#050505] font-sans text-slate-800 dark:text-slate-200 flex flex-col overflow-hidden p-4 gap-4">
      
      {/* 1. COMPACT HEADER WITH FLOW */}
      <div className="flex-none flex items-center justify-between px-2">
         <div className="flex items-center gap-6">
            <h1 className="text-xl font-black text-slate-900 dark:text-white tracking-tight">Request Absence</h1>
            
            {/* The Approval Flow - Right next to title */}
            <div className="hidden md:flex items-center gap-2 pl-6 border-l border-slate-200 dark:border-white/10">
               {COMPANY_CONFIG.approvers.map((p, i) => (
                  <React.Fragment key={i}>
                     <div className="flex items-center gap-2 bg-white dark:bg-[#151515] pl-1 pr-3 py-1 rounded-full border border-slate-200 dark:border-white/10 shadow-sm">
                        <div className="h-5 w-5 rounded-full bg-indigo-600 text-white flex items-center justify-center text-[9px] font-bold">{p.avatar}</div>
                        <div className="flex flex-col leading-none">
                           <span className="text-[9px] font-bold uppercase text-slate-400">{i === 0 ? 'First' : 'Final'}</span>
                           <span className="text-[10px] font-bold text-slate-900 dark:text-white">{p.name}</span>
                        </div>
                     </div>
                     {i < COMPANY_CONFIG.approvers.length - 1 && <div className="w-4 h-[1px] bg-slate-300 dark:bg-white/20" />}
                  </React.Fragment>
               ))}
            </div>
         </div>

         <div className="flex items-center gap-2 bg-emerald-500/10 px-3 py-1.5 rounded-full border border-emerald-500/20">
            <div className="h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
            <span className="text-[10px] font-bold text-emerald-600 uppercase tracking-wide">System Live</span>
         </div>
      </div>

      {/* 2. MAIN SINGLE SCREEN CONTENT */}
      <div className="flex-1 flex gap-4 overflow-hidden min-h-0">
        
        {/* LEFT: CALENDAR (Flex-1 to take available space) */}
        <div className="flex-1 bg-white dark:bg-[#111] rounded-3xl border border-slate-200 dark:border-white/10 shadow-sm flex flex-col overflow-hidden">
             
             {/* Toolbar */}
             <div className="flex-none px-6 py-4 flex items-center justify-between border-b border-slate-100 dark:border-white/5">
                <div className="flex items-center gap-4">
                   <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-2 hover:bg-slate-100 dark:hover:bg-white/5 rounded-xl transition-colors"><ChevronLeft className="h-4 w-4" /></button>
                   <h2 className="text-lg font-black w-32 text-center uppercase tracking-tight">{currentDate.toLocaleString('default', { month: 'long', year: 'numeric' })}</h2>
                   <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-2 hover:bg-slate-100 dark:hover:bg-white/5 rounded-xl transition-colors"><ChevronRight className="h-4 w-4" /></button>
                </div>
                
                <div className="flex bg-slate-100 dark:bg-white/5 p-1 rounded-xl">
                   {['single', 'range', 'multi'].map((m) => (
                      <button key={m} onClick={() => { setMode(m as any); setRange({start:"", end:""}); setMultiDates([]); }} className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${mode === m ? "bg-white dark:bg-[#222] shadow-sm text-indigo-600" : "text-slate-400 hover:text-slate-600"}`}>
                         {m}
                      </button>
                   ))}
                </div>
             </div>

             {/* Grid (Overflows here) */}
             <div className="flex-1 p-6 overflow-y-auto">
                <div className="grid grid-cols-7 gap-1 h-full content-start">
                   {['M', 'T', 'W', 'T', 'F', 'S', 'S'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 dark:text-slate-600 mb-2">{d}</div>)}
                   
                   {Array.from({ length: calendarData.firstDayOfWeek }).map((_, i) => <div key={`e-${i}`} />)}
                   
                   {Array.from({ length: calendarData.daysInMonth }).map((_, i) => {
                      const day = i + 1;
                      const y = calendarData.year;
                      const m = calendarData.month + 1;
                      const dateStr = `${y}-${m < 10 ? '0' + m : m}-${day < 10 ? '0' + day : day}`;
                      
                      const holiday = COMPANY_CONFIG.holidays.find(h => h.date === dateStr);
                      const existing = COMPANY_CONFIG.history.find(r => r.date === dateStr);
                      
                      let isSelected = false, inRange = false;
                      if (mode === "multi") isSelected = multiDates.includes(dateStr);
                      else { isSelected = range.start === dateStr || range.end === dateStr; inRange = range.start && range.end && dateStr > range.start && dateStr < range.end; }

                      // Robust Styling Logic
                      let btnClass = "border border-slate-100 dark:border-white/5 bg-white dark:bg-[#151515] text-slate-600 dark:text-slate-400 hover:border-indigo-400";
                      let isDisabled = false;

                      if (existing?.status === 'approved') { btnClass = "bg-emerald-50 dark:bg-emerald-900/10 border-emerald-100 text-emerald-600 opacity-50"; isDisabled = true; }
                      else if (existing?.status === 'pending') { btnClass = "bg-amber-50 dark:bg-amber-900/10 border-amber-100 text-amber-600 opacity-80"; isDisabled = true; }
                      else if (isSelected) btnClass = "bg-indigo-600 text-white border-indigo-600 shadow-md z-10 scale-105";
                      else if (inRange) btnClass = "bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 border-indigo-100 dark:border-indigo-800";
                      else if (holiday) btnClass = "bg-rose-50 dark:bg-rose-900/10 border-rose-100 text-rose-500";

                      return (
                         <button key={day} onClick={() => handleDateClick(day)} disabled={isDisabled} className={`relative min-h-[3.5rem] rounded-xl text-left p-2 transition-all group ${btnClass}`}>
                            <span className="text-xs font-bold">{day}</span>
                            {holiday && <span className="absolute bottom-1 left-2 text-[8px] font-bold uppercase truncate max-w-[90%]">{holiday.name}</span>}
                            {isSelected && <Sparkles className="absolute top-1.5 right-1.5 h-3 w-3 text-indigo-200 animate-pulse" />}
                         </button>
                      )
                   })}
                </div>
             </div>
        </div>

        {/* RIGHT: SIDEBAR (Fixed Width) */}
        <div className="w-[360px] flex flex-col gap-4">
           <div className="flex-1 bg-white dark:bg-[#111] rounded-3xl border border-slate-200 dark:border-white/10 shadow-xl flex flex-col overflow-hidden">
              
              {/* Form Content */}
              <div className="flex-1 p-5 space-y-5 overflow-y-auto custom-scrollbar">
                 
                 {/* 1. Type Selector */}
                 <div className="relative" ref={dropdownRef}>
                    <label className="text-[9px] font-black uppercase text-slate-400 mb-2 block tracking-widest">Leave Category</label>
                    <button onClick={() => setIsDropdownOpen(!isDropdownOpen)} className="w-full flex items-center justify-between bg-white dark:bg-[#1a1a1a] border border-slate-200 dark:border-white/10 rounded-2xl p-3 hover:border-indigo-500 transition-all shadow-sm group">
                       <div className="flex items-center gap-3"><div className={`p-2 rounded-xl ${selectedType.bg} ${selectedType.color}`}><selectedType.icon className="h-4 w-4" /></div><span className="text-sm font-bold">{selectedType.label}</span></div>
                       <ChevronDown className={`h-4 w-4 text-slate-400 transition-transform ${isDropdownOpen ? 'rotate-180' : ''}`} />
                    </button>
                    {isDropdownOpen && (
                       <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-[#1a1a1a] border border-slate-200 dark:border-white/10 rounded-2xl shadow-2xl z-50 p-1">
                          {COMPANY_CONFIG.leaveTypes.map(t => (
                             <button key={t.id} onClick={() => { setTypeId(t.id); setIsDropdownOpen(false); }} className="w-full flex items-center justify-between p-2.5 hover:bg-slate-50 dark:hover:bg-white/5 rounded-xl transition-colors">
                                <div className="flex items-center gap-3"><div className={`p-1.5 rounded-lg ${t.bg} ${t.color}`}><t.icon className="h-3.5 w-3.5" /></div><span className="text-xs font-bold">{t.label}</span></div>
                                <span className="text-[10px] font-bold text-slate-500">{t.balance}d</span>
                             </button>
                          ))}
                       </div>
                    )}
                 </div>

                 {/* 2. Stats Cards */}
                 <div className="grid grid-cols-2 gap-3">
                    <div className="bg-slate-50 dark:bg-white/5 p-4 rounded-2xl border border-slate-100 dark:border-white/5 text-center">
                       <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Duration</p>
                       <p className="text-xl font-black text-slate-900 dark:text-white mt-1">{stats.days}<span className="text-xs text-slate-400 ml-1">days</span></p>
                    </div>
                    <div className="bg-slate-50 dark:bg-white/5 p-4 rounded-2xl border border-slate-100 dark:border-white/5 text-center">
                       <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Deduction</p>
                       <p className="text-xl font-black text-rose-500 mt-1">-{stats.deduction}</p>
                    </div>
                 </div>

                 {/* 3. Conditional Inputs */}
                 {isCoverRequired && (
                    <div className="animate-in slide-in-from-right-4 fade-in duration-300">
                       <label className="text-[9px] font-black uppercase text-slate-400 mb-2 block tracking-widest">Delegate To <span className="text-rose-500">*</span></label>
                       <div className="relative">
                          <select value={coverId} onChange={(e) => setCoverId(e.target.value)} className="w-full appearance-none bg-slate-50 dark:bg-white/5 border border-slate-100 dark:border-white/5 rounded-2xl p-3 text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none">
                             <option value="">Select colleague...</option>
                             {COMPANY_CONFIG.colleagues.map(c => <option key={c.id} value={c.id}>{c.name} ({c.role})</option>)}
                          </select>
                          <User className="absolute right-3 top-3.5 h-4 w-4 text-slate-400 pointer-events-none" />
                       </div>
                    </div>
                 )}

                 {/* 4. Reason */}
                 <div>
                    <label className="text-[9px] font-black uppercase text-slate-400 mb-2 block tracking-widest">Reason</label>
                    <textarea 
                       className="w-full bg-slate-50 dark:bg-white/5 border border-slate-100 dark:border-white/5 rounded-2xl p-4 text-xs font-medium focus:ring-2 focus:ring-indigo-500 outline-none resize-none min-h-[100px]" 
                       placeholder="Please provide context for your request..." 
                       value={reason} 
                       onChange={(e) => setReason(e.target.value)} 
                    />
                 </div>

                 {/* 5. File Upload */}
                 {selectedType.requiresDoc && (
                    <div>
                       <label className="text-[9px] font-black uppercase text-slate-400 mb-2 block tracking-widest">Medical Proof <span className="text-rose-500">*</span></label>
                       <div onClick={() => fileInputRef.current?.click()} className={`border-2 border-dashed rounded-2xl h-14 flex items-center justify-center cursor-pointer transition-all gap-2 ${file ? "border-emerald-500 bg-emerald-50 dark:bg-emerald-900/10" : "border-slate-200 dark:border-white/10 hover:border-indigo-400"}`}>
                          <input type="file" className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && setFile(e.target.files[0])} />
                          {file ? <span className="text-xs font-bold text-emerald-600 flex items-center gap-2"><CheckCircle2 className="h-4 w-4"/> {file.name.slice(0,18)}...</span> : <div className="flex items-center gap-2 text-slate-400"><UploadCloud className="h-4 w-4" /> <span className="text-[10px] font-bold">Upload Document</span></div>}
                       </div>
                    </div>
                 )}
              </div>
              
              {/* Footer Button */}
              <div className="p-5 border-t border-slate-100 dark:border-white/5 bg-slate-50/50 dark:bg-white/[0.02]">
                 <button 
                    disabled={isBtnDisabled} 
                    className={`w-full py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl shadow-indigo-500/10 transition-all ${!isBtnDisabled ? "bg-slate-900 dark:bg-indigo-600 text-white hover:scale-[1.02]" : "bg-slate-200 dark:bg-white/10 text-slate-400 cursor-not-allowed"}`}
                 >
                    Submit Request
                 </button>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
}